-- Returns from a customer: movement 651 and the quantity that has come back.
--
-- SAP posts a customer return with movement 651, generated by SD out of the returns delivery, and it
-- posts it into *returns stock* — "blocked stock returns" in SAP's own words — which is deliberately
-- NOT VALUATED: the goods are back in the warehouse but they are not the company's stock again until
-- somebody has looked at them, so 651 generates no accounting document at all. The document is
-- generated later, by the transfer that takes the goods out of returns stock and into valuated stock
-- (453 unrestricted, 457 quality inspection, 459 blocked). This migration carries the two facts that
-- make that postable; the posting itself comes with the service that reads them.
--
-- The first fact is a reference category. A returns receipt is not free-standing: it names the
-- delivery the goods left on, which is what makes "how much may come back" a question with an answer
-- instead of a quantity the stores type in. Every reference category this table has gained has
-- widened the same constraint (9071, 9077, 9091), and this is the next one.
--
-- The second fact is the quantity that has already come back, on the delivery line. It is a column
-- with a constraint rather than a sum over material documents for the same reason the delivery's own
-- quantities are: the refusal has to hold for every writer, not for the one service that thought of
-- it. A line cannot return more than left the plant, and it cannot un-return.

alter table public.movement_type
  drop constraint if exists movement_type_reference_ck;
alter table public.movement_type
  add constraint movement_type_reference_ck
  check (reference_category in (
    'PURCHASE_ORDER', 'MATERIAL_DOCUMENT', 'RESERVATION', 'PRODUCTION_ORDER', 'PHYSICAL_INVENTORY',
    -- A returns receipt names the delivery the goods went out on, so the quantity coming back can be
    -- judged against the quantity that left.
    'SALES_DELIVERY'
  ));

alter table public.delivery_line
  add column if not exists returned_quantity numeric(13, 3) not null default 0;

-- How much of the issued quantity has been received back onto this line. Bounded by what was issued,
-- so a return cannot invent goods the plant never sent and cannot, by being posted twice, make more
-- come back than left.
alter table public.delivery_line
  drop constraint if exists delivery_line_returned_ck;
alter table public.delivery_line
  add constraint delivery_line_returned_ck
  check (returned_quantity >= 0 and returned_quantity <= goods_issue_quantity);

comment on column public.delivery_line.returned_quantity is
  'How much of the goods-issued quantity has been received back from the customer (movement 651). Returns stock is not valuated, so this quantity carries no value: it becomes stock again only when a transfer takes it out of returns stock into valuated stock.';
